import{_ as h,o as t,c as a,a2 as g}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Quên và ôn tập ảnh hưởng gợi ý ra sao","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/retention.md","filePath":"decisions/retention.md"}'),i={name:"decisions/retention.md"};function c(o,n,r,u,e,l){return t(),a("div",null,[...n[0]||(n[0]=[g('<h1 id="quen-va-on-tap-anh-huong-goi-y-ra-sao" tabindex="-1">Quên và ôn tập ảnh hưởng gợi ý ra sao <a class="header-anchor" href="#quen-va-on-tap-anh-huong-goi-y-ra-sao" aria-label="Permalink to &quot;Quên và ôn tập ảnh hưởng gợi ý ra sao&quot;">​</a></h1><p>Trên trang này# Quên và ôn tập ảnh hưởng gợi ý ra sao <a href="#quen-va-on-tap-anh-huong-goi-y-ra-sao">​</a> Mastery cao trong quá khứ không có nghĩa learner làm được hôm nay. Nemo12 lưu hai con số riêng biệt cho hai câu hỏi này — và việc tách chúng ra tiết kiệm rất nhiều thời gian cho learner.</p><h2 id="quy-tac-goc-mastery-khong-tu-giam-​" tabindex="-1">Quy tắc gốc: mastery không tự giảm <a href="#quy-tac-goc-mastery-khong-tu-giam">​</a> <a class="header-anchor" href="#quy-tac-goc-mastery-khong-tu-giam-​" aria-label="Permalink to &quot;Quy tắc gốc: mastery không tự giảm [​](#quy-tac-goc-mastery-khong-tu-giam)&quot;">​</a></h2><p>Nhiều hệ thống làm điều này: mastery 0.90, ba mươi ngày không dùng, tự động hạ xuống 0.64. Nemo12 <strong>cấm</strong> cách làm đó. Con số 0.90 là một sự thật lịch sử — đã có lúc learner làm được ở mức đó, và không thời gian nào xoá được sự thật ấy. Cái thay đổi là một con số <strong>thứ hai</strong>: textmastery lịch sử = 0.90 (giữ nguyên) khả năng còn nhớ = 0.64 (con số riêng, có giảm)Nhờ tách hai chiều, hệ thống phân biệt được hai tình huống mà bề ngoài giống hệt nhau — và cần hai cách xử lý hoàn toàn khác nhau.</p><h2 id="ba-tinh-huong-trong-giong-nhau-​" tabindex="-1">Ba tình huống trông giống nhau <a href="#ba-tinh-huong-trong-giong-nhau">​</a> <a class="header-anchor" href="#ba-tinh-huong-trong-giong-nhau-​" aria-label="Permalink to &quot;Ba tình huống trông giống nhau [​](#ba-tinh-huong-trong-giong-nhau)&quot;">​</a></h2><p>Tình huốngDấu hiệuXử lý đúng<strong>Đã quên</strong>Từng vững, giờ làm không được1–3 câu đánh thức. <strong>Không dạy lại từ đầu.****Chưa từng học</strong>Chưa bao giờ có bằng chứng vữngHọc đầy đủ, đường học bình thường<strong>Lỗi hoàn cảnh</strong>Sai nhưng đang ốm, mệt, vội, đọc nhầm đềKhông hạ gì cả. Chờ thêm bằng chứng.Xử lý tình huống đầu như tình huống thứ hai là cách lãng phí thời gian phổ biến nhất trong việc ôn tập: bắt một đứa trẻ học lại cả chương khi nó chỉ cần hai câu để nhớ ra.</p><h2 id="on-hieu-qua-thi-cang-it-phai-on-​" tabindex="-1">Ôn hiệu quả thì càng ít phải ôn <a href="#on-hieu-qua-thi-cang-it-phai-on">​</a> <a class="header-anchor" href="#on-hieu-qua-thi-cang-it-phai-on-​" aria-label="Permalink to &quot;Ôn hiệu quả thì càng ít phải ôn [​](#on-hieu-qua-thi-cang-it-phai-on)&quot;">​</a></h2><p>Trí nhớ mờ dần theo một đường cong, và tốc độ mờ phụ thuộc vào <strong>độ ổn định</strong> của kiến thức đó. Mỗi lần nhớ lại thành công làm độ ổn định tăng lên — nên lần ôn kế tiếp có thể để xa hơn: textNhưng chuỗi này không cố định. Nó phụ thuộc vào chất lượng của lần nhớ lại: Cách learner nhớ lạiTác độngChỉ đọc lại lời giảiRất nhẹChọn đúng trong các phương ánNhẹĐúng nhưng có gợi ýVừa<strong>Tự nhớ lại đúng, không gợi ý****Mạnh</strong> — nhất là sau một khoảng lâu<strong>Đúng trong bài trộn lẫn, ngữ cảnh lạ****Mạnh nhất</strong>Và nếu learner tự khai là <strong>đoán</strong> mà vẫn đúng — hệ thống không tính đó là một lần nhớ lại độc lập. Trí nhớ không được bồi bằng may mắn. Ngược lại, khi nhớ lại thất bại, khoảng cách co lại — hệ thống học ra rằng learner quên phần này nhanh hơn nó tưởng, và điều chỉnh riêng cho learner đó.</p><h2 id="tri-nho-thap-khong-tu-đong-nghia-la-phai-on-ngay-​" tabindex="-1">Trí nhớ thấp không tự động nghĩa là phải ôn ngay <a href="#tri-nho-thap-khong-tu-đong-nghia-la-phai-on-ngay">​</a> <a class="header-anchor" href="#tri-nho-thap-khong-tu-đong-nghia-la-phai-on-ngay-​" aria-label="Permalink to &quot;Trí nhớ thấp không tự động nghĩa là phải ôn ngay [​](#tri-nho-thap-khong-tu-đong-nghia-la-phai-on-ngay)&quot;">​</a></h2><p>Đây là chi tiết quyết định chất lượng của toàn bộ hệ thống. Mức ưu tiên ôn tập không chỉ nhìn vào việc đã quên bao nhiêu: textMức ưu tiên ôn = Nguy cơ quên × Tầm quan trọng × Liên quan mục tiêu × Giá trị làm nền cho phần khác × Mức khẩn về thời gianHệ quả cụ thể:</p><ul><li>Một phần còn nhớ 0.60 nhưng không phục vụ mục tiêu nào → ưu tiên <strong>thấp</strong>. Có thể bỏ hẳn.</li><li>Một phần còn nhớ 0.68 nhưng thi sau 5 ngày → ưu tiên <strong>rất cao</strong>.</li><li>Một phần chặn hàng chục bài khác được ôn <strong>sớm hơn</strong> một phần độc lập dù phần kia quên nhiều hơn. Hai phần cùng còn nhớ 0.60: phần phục vụ kỳ thi sau 12 ngày thắng phần phục vụ kỳ thi sau 9 tháng. Không phải vì quên nhiều hơn — vì mục tiêu gấp hơn.</li></ul><h2 id="khi-chua-chac-thi-đo-đung-bat-hoc-lai-​" tabindex="-1">Khi chưa chắc thì đo, đừng bắt học lại <a href="#khi-chua-chac-thi-đo-đung-bat-hoc-lai">​</a> <a class="header-anchor" href="#khi-chua-chac-thi-đo-đung-bat-hoc-lai-​" aria-label="Permalink to &quot;Khi chưa chắc thì đo, đừng bắt học lại [​](#khi-chua-chac-thi-đo-đung-bat-hoc-lai)&quot;">​</a></h2><p>Nếu ước lượng còn nhớ là 0.55 nhưng độ tin cậy của ước lượng đó chỉ 0.31, hệ thống <strong>không</strong> giao ngay một chương ôn tập. Nó hỏi 1–3 câu nhớ lại:</p><ul><li>Learner làm được dễ dàng → ước lượng nhảy lên 0.88 ngay. Không cần ôn gì cả.</li><li>Learner không làm được → xác nhận đã quên thật, và bắt đầu ôn ở đúng mức cần thiết. Đây là cơ chế chống &quot;ôn thừa&quot; — và nó tiết kiệm rất nhiều thời gian mà không đánh đổi gì.</li></ul><h2 id="khong-co-no-on-tap-​" tabindex="-1">Không có nợ ôn tập <a href="#khong-co-no-on-tap">​</a> <a class="header-anchor" href="#khong-co-no-on-tap-​" aria-label="Permalink to &quot;Không có nợ ôn tập [​](#khong-co-no-on-tap)&quot;">​</a></h2><p>Learner nghỉ hai tuần và quay lại <strong>không</strong> thấy &quot;187 bài quá hạn&quot;. Danh sách ôn được tính lại từ đầu mỗi ngày. Câu hỏi không phải &quot;còn nợ bao nhiêu&quot; mà là <em>&quot;trong tất cả những gì đã mờ đi, hôm nay ôn cái nào đáng nhất?&quot;</em>. Có 43 ứng viên thì hôm nay chọn 5 cái giá trị nhất; mai tính lại từ đầu. Một số phần sẽ bị bỏ hẳn vì không còn phục vụ mục tiêu nào — đó là quyết định đúng, không phải thiếu sót. Ngoài ra, khi con làm một bài mới có dùng tới kiến thức cũ và dùng đúng, kiến thức cũ đó được tính là vừa được ôn — <strong>không cần một buổi ôn riêng cho nó</strong>.</p><h2 id="learner-va-phu-huynh-thay-gi-​" tabindex="-1">Learner và phụ huynh thấy gì <a href="#learner-va-phu-huynh-thay-gi">​</a> <a class="header-anchor" href="#learner-va-phu-huynh-thay-gi-​" aria-label="Permalink to &quot;Learner và phụ huynh thấy gì [​](#learner-va-phu-huynh-thay-gi)&quot;">​</a></h2><p><strong>Learner</strong> thấy một khối &quot;Ôn nhanh&quot; ngắn gọn, viết bằng lời tử tế: <em>&quot;Tam giác đồng dạng — 8 phút. Con làm tốt phần này, nhưng 24 ngày chưa dùng tới. Hai câu để giữ cho thật chắc.&quot;</em> Hệ thống <strong>không bao giờ</strong> nói &quot;con đã quên&quot;. Câu đó vừa không chính xác — đây là ước lượng, không phải sự thật — vừa không giúp gì cho một đứa trẻ. <strong>Phụ huynh</strong> thấy các nhóm nhãn theo môn: <em>Đang chắc · Cần nhắc lại sớm · Có nguy cơ quên · Nên ôn lại</em>. Không có phương trình nào, nhưng có một phân biệt được giữ rõ: <strong>&quot;từng vững nay đang mờ&quot;</strong> khác hẳn <strong>&quot;chưa từng vững&quot;</strong>. Quên không phải thất bại. Nó là cách trí nhớ con người vận hành. Việc của hệ thống là biết cái gì đang mờ, cái nào đáng cứu, và cứu bằng cách rẻ nhất. <a href="/mental-models/">Sang nhóm: Parent Mental Models →</a></p>',18)])])}const p=h(i,[["render",c]]);export{m as __pageData,p as default};
